#include <stdint.h>
#include "term.h"
struct Term {
	void (*kbd_cb)(void *, int scan_code, int is_pressed);
	void *kbd;
#ifdef BUILD_ESP32
	struct {
		int code, shift, mod;
		uint32_t since;
	} held[8];
	int nheld;
#endif
};

